content.content:
     1→// handlers_spectrum.go — gamma spectrum data
     2→//
     3→// Serves gamma spectrum data for markers: JSON metadata, or downloads in
     4→// JSON, CSV, N42, or SPE format. Spectra are radiation measurements from
     5→// detectors at specific map locations.
     6→package web
     7→
     8→import (
     9→	"encoding/json"
    10→	"fmt"
    11→	"log"
    12→	"net/http"
    13→	"strconv"
    14→	"strings"
    15→	"time"
    16→)
    17→
    18→// spectrum returns spectrum JSON for a marker. If the path contains "/download",
    19→// it delegates to spectrumDownload instead.
    20→//
    21→// Route: GET /api/spectrum/{markerID}
    22→func (s *Server) spectrum(w http.ResponseWriter, r *http.Request) {
    23→	if strings.Contains(r.URL.Path, "/download") {
    24→		s.spectrumDownload(w, r)
    25→		return
    26→	}
    27→	if s.DB == nil || s.DB.DB == nil {
    28→		http.Error(w, "Database not available", http.StatusServiceUnavailable)
    29→		return
    30→	}
    31→	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
    32→	if len(parts) < 3 {
    33→		http.Error(w, "Marker ID not provided", http.StatusBadRequest)
    34→		return
    35→	}
    36→	markerID, err := strconv.ParseInt(parts[2], 10, 64)
    37→	if err != nil {
    38→		http.Error(w, "Invalid marker ID", http.StatusBadRequest)
    39→		return
    40→	}
    41→	ctx, cancel := WithMinimumDeadline(r.Context(), 30*time.Second)
    42→	defer cancel()
    43→	spectrum, err := s.DB.GetSpectrum(ctx, markerID)
    44→	if err != nil {
    45→		log.Printf("Error fetching spectrum for marker %d: %v", markerID, err)
    46→		http.Error(w, "Error fetching spectrum", http.StatusInternalServerError)
    47→		return
    48→	}
    49→	if spectrum == nil {
    50→		http.Error(w, "No spectrum found for this marker", http.StatusNotFound)
    51→		return
    52→	}
    53→	w.Header().Set("Content-Type", "application/json")
    54→	json.NewEncoder(w).Encode(spectrum)
    55→}
    56→
    57→// spectrumDownload returns the spectrum as a downloadable file.
    58→//
    59→// Route: GET /api/spectrum/{markerID}/download?format=json|csv|n42|spe
    60→//
    61→// format: json (default), csv, n42, or spe. N42 and SPE return raw source
    62→// data when available; otherwise 404.
    63→func (s *Server) spectrumDownload(w http.ResponseWriter, r *http.Request) {
    64→	if s.DB == nil || s.DB.DB == nil {
    65→		http.Error(w, "Database not available", http.StatusServiceUnavailable)
    66→		return
    67→	}
    68→	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
    69→	if len(parts) < 3 {
    70→		http.Error(w, "Marker ID not provided", http.StatusBadRequest)
    71→		return
    72→	}
    73→	markerID, err := strconv.ParseInt(parts[2], 10, 64)
    74→	if err != nil {
    75→		http.Error(w, "Invalid marker ID", http.StatusBadRequest)
    76→		return
    77→	}
    78→	format := r.URL.Query().Get("format")
    79→	if format == "" {
    80→		format = "json"
    81→	}
    82→	ctx, cancel := WithMinimumDeadline(r.Context(), 30*time.Second)
    83→	defer cancel()
    84→	spectrum, err := s.DB.GetSpectrum(ctx, markerID)
    85→	if err != nil {
    86→		log.Printf("Error fetching spectrum for marker %d: %v", markerID, err)
    87→		http.Error(w, "Error fetching spectrum", http.StatusInternalServerError)
    88→		return
    89→	}
    90→	if spectrum == nil {
    91→		http.Error(w, "No spectrum found for this marker", http.StatusNotFound)
    92→		return
    93→	}
    94→	switch strings.ToLower(format) {
    95→	case "json":
    96→		w.Header().Set("Content-Type", "application/json")
    97→		w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=spectrum_%d.json", markerID))
    98→		json.NewEncoder(w).Encode(spectrum)
    99→	case "csv":
   100→		w.Header().Set("Content-Type", "text/csv")
   101→		w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=spectrum_%d.csv", markerID))
   102→		fmt.Fprintf(w, "Channel,Energy_keV,Counts\n")
   103→		for i, count := range spectrum.Channels {
   104→			energy := 0.0
   105→			if spectrum.Calibration != nil {
   106→				ch := float64(i)
   107→				energy = spectrum.Calibration.A + spectrum.Calibration.B*ch + spectrum.Calibration.C*ch*ch
   108→			}
