    11→// ChannelToEnergy converts a channel number to energy (keV) using calibration coefficients.
    12→// Formula: Energy = A + B*channel + C*channel^2
    13→func ChannelToEnergy(channel int, cal *database.EnergyCalibration) float64 {
    14→	if cal == nil {
    15→		return 0
    16→	}
    17→	ch := float64(channel)
    18→	return cal.A + cal.B*ch + cal.C*ch*ch
    19→}
    20→
    21→// EnergyToChannel converts energy (keV) to approximate channel number using calibration.
    22→// This is the inverse of ChannelToEnergy, solving the quadratic equation.
    23→func EnergyToChannel(energyKeV float64, cal *database.EnergyCalibration) int {
    24→	if cal == nil {
    25→		return 0
    26→	}
    27→
    28→	// For quadratic: c*x^2 + b*x + (a-E) = 0
    29→	// Using quadratic formula: x = (-b + sqrt(b^2 - 4ac)) / 2c
    30→	if cal.C != 0 {
    31→		discriminant := cal.B*cal.B - 4*cal.C*(cal.A-energyKeV)
    32→		if discriminant < 0 {
    33→			return 0
    34→		}
    35→		return int((-cal.B + math.Sqrt(discriminant)) / (2 * cal.C))
    36→	}
    37→
    38→	// Linear calibration: b*x + a = E
    39→	if cal.B != 0 {
    40→		return int((energyKeV - cal.A) / cal.B)
    41→	}
    42→
    43→	return 0
    44→}
