   101→// DetectPeaks performs simple peak detection on spectrum data.
   102→// A peak is defined as a local maximum that exceeds the threshold (as a fraction of max counts).
   103→// This is a basic implementation - more sophisticated algorithms exist for real peak analysis.
   104→func DetectPeaks(channels []int, threshold float64, cal *database.EnergyCalibration) []Peak {
   105→	if len(channels) < 3 {
   106→		return nil
   107→	}
   108→
   109→	// Find maximum counts for threshold calculation
   110→	maxCounts := 0
   111→	for _, c := range channels {
   112→		if c > maxCounts {
   113→			maxCounts = c
   114→		}
   115→	}
   116→
   117→	if maxCounts == 0 {
   118→		return nil
   119→	}
   120→
   121→	minCounts := int(float64(maxCounts) * threshold)
   122→	var peaks []Peak
   123→
   124→	// Scan for local maxima
   125→	for i := 1; i < len(channels)-1; i++ {
   126→		if channels[i] > channels[i-1] && channels[i] > channels[i+1] && channels[i] >= minCounts {
   127→			peak := Peak{
   128→				Channel: i,
   129→				Counts:  channels[i],
   130→			}
   131→			if cal != nil {
   132→				peak.Energy = ChannelToEnergy(i, cal)
   133→			}
   134→			peaks = append(peaks, peak)
   135→		}
   136→	}
   137→
   138→	return peaks
   139→}
