   141→// IntegrateEnergyRange calculates the total counts in a specified energy range.
   142→// Returns the sum of counts in channels corresponding to energies between minKeV and maxKeV.
   143→func IntegrateEnergyRange(channels []int, minKeV, maxKeV float64, cal *database.EnergyCalibration) int {
   144→	if cal == nil || len(channels) == 0 {
   145→		return 0
   146→	}
   147→
   148→	minChannel := EnergyToChannel(minKeV, cal)
   149→	maxChannel := EnergyToChannel(maxKeV, cal)
   150→
   151→	if minChannel < 0 {
   152→		minChannel = 0
   153→	}
   154→	if maxChannel >= len(channels) {
   155→		maxChannel = len(channels) - 1
   156→	}
   157→
   158→	total := 0
   159→	for i := minChannel; i <= maxChannel; i++ {
   160→		total += channels[i]
   161→	}
   162→
   163→	return total
   164→}
