   136→	if err := parseSPEDataSection(spe, dataLines, dataStart, dataEnd); err != nil {
   137→		return nil, err
   138→	}
   139→
   140→	if err := parseSPECalibration(spe, calLines); err != nil {
   141→		// Non-fatal: use default calibration if parsing fails
   142→		fmt.Printf("SPE Debug: Could not parse calibration, using defaults: %v\n", err)
   143→	}
   144→
   145→	// Validate we got spectrum data
   146→	if len(spe.Data) == 0 {
   147→		return nil, fmt.Errorf("no spectrum data found in SPE file")
   148→	}
   149→
   150→	return spe, nil
   151→}
