   153→// parseSPEDataSection parses the $DATA section
   154→func parseSPEDataSection(spe *SPEFile, lines []string, start, end int) error {
   155→	if start == 0 && end == 0 {
   156→		return fmt.Errorf("no $DATA section found")
   157→	}
   158→
   159→	expectedChannels := end - start + 1
   160→	spe.Data = make([]int, 0, expectedChannels)
   161→
   162→	// Re-parse data lines for channel counts
   163→	scanner := bufio.NewScanner(bytes.NewReader([]byte(strings.Join(lines, "\n"))))
   164→	for scanner.Scan() {
   165→		line := strings.TrimSpace(scanner.Text())
   166→		if line == "" {
   167→			continue
   168→		}
   169→
   170→		// Skip the start/end line
   171→		fields := strings.Fields(line)
   172→		if len(fields) == 2 {
   173→			// Check if this looks like the start/end declaration
   174→			if val1, err1 := strconv.Atoi(fields[0]); err1 == nil {
   175→				if val2, err2 := strconv.Atoi(fields[1]); err2 == nil {
   176→					if val1 == start && val2 == end {
   177→						continue // Skip this line
   178→					}
   179→				}
   180→			}
   181→		}
   182→
   183→		// Parse channel count
   184→		count, err := strconv.Atoi(line)
   185→		if err != nil {
   186→			return fmt.Errorf("parse channel count %q: %w", line, err)
   187→		}
   188→		spe.Data = append(spe.Data, count)
   189→	}
   190→
   191→	if len(spe.Data) == 0 {
   192→		return fmt.Errorf("no channel data parsed")
   193→	}
   194→
   195→	return nil
   196→}
   197→
   198→// parseSPECalibration parses the $MCA_CAL section
   199→func parseSPECalibration(spe *SPEFile, lines []string) error {
   200→	if len(lines) == 0 {
   201→		return fmt.Errorf("no calibration data")
   202→	}
   203→
   204→	// First line is number of coefficients
   205→	coeffs := make([]float64, 0)
   206→
   207→	for i, line := range lines {
   208→		line = strings.TrimSpace(line)
   209→		if line == "" {
   210→			continue
   211→		}
   212→
   213→		if i == 0 {
   214→			// First line is number of coefficients (we just skip it)
   215→			continue
   216→		} else {
   217→			// Coefficient values
   218→			val, err := strconv.ParseFloat(line, 64)
   219→			if err != nil {
   220→				continue
   221→			}
   222→			coeffs = append(coeffs, val)
   223→		}
   224→	}
   225→
   226→	// Need at least 2 coefficients for linear calibration (a, b)
   227→	if len(coeffs) < 2 {
   228→		return fmt.Errorf("insufficient calibration coefficients: got %d, need at least 2", len(coeffs))
   229→	}
   230→
   231→	spe.MCACalib = &database.EnergyCalibration{
   232→		A: coeffs[0], // Offset
   233→		B: coeffs[1], // Linear
   234→		C: 0,         // Quadratic (default to 0 if not present)
   235→	}
   236→
   237→	if len(coeffs) >= 3 {
   238→		spe.MCACalib.C = coeffs[2]
   239→	}
   240→
   241→	return nil
   242→}
   243→
   244→// convertSPEToSpectrum converts an SPEFile to database format
   245→func convertSPEToSpectrum(spe *SPEFile, rawData []byte) (*database.Spectrum, *database.Marker, error) {
   246→	if len(spe.Data) == 0 {
   247→		return nil, nil, fmt.Errorf("empty spectrum data")
   248→	}
   249→
   250→	// Extract timing information
   251→	liveTime := 0.0
   252→	realTime := 0.0
   253→	if len(spe.MeasTim) >= 2 {
   254→		liveTime = spe.MeasTim[0]
   255→		realTime = spe.MeasTim[1]
   256→	} else if len(spe.MeasTim) == 1 {
   257→		liveTime = spe.MeasTim[0]
   258→		realTime = spe.MeasTim[0]
   259→	}
   260→
   261→	// Set up energy calibration
   262→	calibration := spe.MCACalib
   263→	if calibration == nil {
   264→		// Default calibration: assume 0-3000 keV range
   265→		calibration = &database.EnergyCalibration{
   266→			A: 0,
   267→			B: 3000.0 / float64(len(spe.Data)),
   268→			C: 0,
   269→		}
   270→	}
   271→
   272→	// Calculate energy range
   273→	energyMin := calibration.A
   274→	lastChannel := float64(len(spe.Data) - 1)
   275→	energyMax := calibration.A + calibration.B*lastChannel + calibration.C*lastChannel*lastChannel
   276→
   277→	// Determine device model
   278→	deviceModel := spe.DeviceModel
   279→	if deviceModel == "" {
   280→		deviceModel = "Unknown SPE Device"
   281→	}
   282→
   283→	// Parse measurement date
   284→	timestamp := time.Now().Unix()
   285→	if spe.DateMea != "" {
   286→		// Try common date formats
   287→		formats := []string{
   288→			"01/02/2006 15:04:05", // MM/DD/YYYY HH:MM:SS
   289→			"02/01/2006 15:04:05", // DD/MM/YYYY HH:MM:SS
   290→			"2006-01-02 15:04:05", // YYYY-MM-DD HH:MM:SS
   291→			time.RFC3339,
   292→		}
   293→		for _, format := range formats {
   294→			if t, err := time.Parse(format, spe.DateMea); err == nil {
   295→				timestamp = t.Unix()
   296→				break
   297→			}
   298→		}
   299→	}
   300→
   301→	spectrum := &database.Spectrum{
   302→		Channels:     spe.Data,
   303→		ChannelCount: len(spe.Data),
   304→		EnergyMinKeV: energyMin,
   305→		EnergyMaxKeV: energyMax,
   306→		LiveTimeSec:  liveTime,
   307→		RealTimeSec:  realTime,
   308→		DeviceModel:  deviceModel,
   309→		Calibration:  calibration,
   310→		SourceFormat: "spe",
   311→		RawData:      rawData,
   312→		CreatedAt:    time.Now().Unix(),
   313→	}
   314→
   315→	// Calculate dose rate and count rate
   316→	doseRate := 0.0
   317→	if liveTime > 0 {
   318→		doseRate = CalculateDoseRate(spe.Data, liveTime, calibration)
   319→	}
   320→
   321→	countRate := 0.0
   322→	if liveTime > 0 {
   323→		countRate = float64(sumChannels(spe.Data)) / liveTime
   324→	}
   325→
   326→	marker := &database.Marker{
   327→		Lat:         0, // Will be set by caller
   328→		Lon:         0, // Will be set by caller
   329→		DoseRate:    doseRate,
   330→		CountRate:   countRate,
   331→		Date:        timestamp,
   332→		HasSpectrum: true,
   333→		Detector:    deviceModel,
   334→	}
   335→
   336→	return spectrum, marker, nil
   337→}
