    87→// ParseN42 parses ANSI N42.42 XML format and extracts spectrum data.
    88→// Returns a slice of Spectrum objects with their associated marker data.
    89→func ParseN42(data []byte) ([]database.Spectrum, []database.Marker, error) {
    90→	var doc N42RadInstrumentData
    91→	if err := xml.Unmarshal(data, &doc); err != nil {
    92→		return nil, nil, fmt.Errorf("parse n42 XML: %w", err)
    93→	}
    94→
    95→	var spectra []database.Spectrum
    96→	var markers []database.Marker
    97→
    98→	fmt.Printf("N42 Debug: Found %d measurements\n", len(doc.Measurements))
    99→
   100→	// Process measurements
   101→	for i, m := range doc.Measurements {
   102→		deviceModel := "Unknown"
   103→		if m.InstrumentInfo != nil && m.InstrumentInfo.InstrumentModel != "" {
   104→			deviceModel = m.InstrumentInfo.InstrumentModel
   105→		}
   106→
   107→		// Extract spectra from detector data
   108→		if m.DetectorData == nil || m.DetectorData.DetectorMeasurement == nil ||
   109→			m.DetectorData.DetectorMeasurement.SpectrumMeasurement == nil {
   110→			fmt.Printf("N42 Debug: Skipping measurement[%d]: no detector/spectrum data\n", i)
   111→			continue
   112→		}
   113→
   114→		specMeas := m.DetectorData.DetectorMeasurement.SpectrumMeasurement
   115→		fmt.Printf("N42 Debug: Processing measurement[%d] with %d spectra\n", i, len(specMeas.Spectra))
   116→
   117→		for j, spec := range specMeas.Spectra {
   118→			spectrum, marker, err := convertN42Spectrum(&spec, &m, deviceModel, data)
   119→			if err != nil {
   120→				fmt.Printf("N42 Debug: Skipping spectrum[%d][%d]: %v\n", i, j, err)
   121→				continue
   122→			}
   123→			if spectrum != nil {
   124→				spectra = append(spectra, *spectrum)
   125→			}
   126→			if marker != nil {
   127→				markers = append(markers, *marker)
   128→			}
   129→		}
   130→	}
   131→
   132→	if len(spectra) == 0 {
   133→		return nil, nil, fmt.Errorf("no valid spectra found in N42 file (found %d measurements)",
   134→			len(doc.Measurements))
   135→	}
   136→
   137→	return spectra, markers, nil
   138→}
