   140→// convertN42Spectrum converts an N42 spectrum to database format.
   141→func convertN42Spectrum(spec *N42Spectrum, m *N42Measurement, deviceModel string, rawData []byte) (*database.Spectrum, *database.Marker, error) {
   142→	// Parse channel data
   143→	channels, err := parseChannelData(spec.ChannelData)
   144→	if err != nil {
   145→		return nil, nil, fmt.Errorf("parse channel data: %w", err)
   146→	}
   147→
   148→	if len(channels) == 0 {
   149→		return nil, nil, fmt.Errorf("empty channel data")
   150→	}
   151→
   152→	// Parse time durations
   153→	liveTime, err := parseN42Duration(spec.LiveTime)
   154→	if err != nil {
   155→		liveTime = 0
   156→	}
   157→
   158→	realTime, err := parseN42Duration(spec.RealTime)
   159→	if err != nil {
   160→		realTime = liveTime
   161→	}
   162→
   163→	// Parse energy calibration - look for Energy type calibration
   164→	calibration := &database.EnergyCalibration{
   165→		A: 0,
   166→		B: 3000.0 / float64(len(channels)),
   167→		C: 0,
   168→	}
   169→
   170→	for _, cal := range spec.Calibration {
   171→		if cal.Type == "Energy" && cal.Equation != nil {
   172→			if parsedCal, err := parseN42CalibrationEquation(cal.Equation.Coefficients); err == nil {
   173→				calibration = parsedCal
   174→				break
   175→			}
   176→		}
   177→	}
   178→
   179→	// Parse measurement time
   180→	timestamp := time.Now().Unix()
   181→	if m.DetectorData != nil && m.DetectorData.StartTime != "" {
   182→		if t, err := time.Parse(time.RFC3339, m.DetectorData.StartTime); err == nil {
   183→			timestamp = t.Unix()
   184→		}
   185→	} else if m.StartTime != "" {
   186→		if t, err := time.Parse(time.RFC3339, m.StartTime); err == nil {
   187→			timestamp = t.Unix()
   188→		}
   189→	}
   190→
   191→	spectrum := &database.Spectrum{
   192→		Channels:     channels,
   193→		ChannelCount: len(channels),
   194→		EnergyMinKeV: 0,
   195→		EnergyMaxKeV: 3000.0, // Standard range, adjust if needed
   196→		LiveTimeSec:  liveTime,
   197→		RealTimeSec:  realTime,
   198→		DeviceModel:  deviceModel,
   199→		Calibration:  calibration,
   200→		SourceFormat: "n42",
   201→		RawData:      rawData,
   202→		CreatedAt:    time.Now().Unix(),
   203→	}
   204→
   205→	// Create a basic marker (no coordinates in this N42 format)
   206→	// User can add coordinates manually or we'll skip marker creation
   207→	doseRate := 0.0
   208→	if liveTime > 0 {
   209→		// Estimate dose rate from spectrum
   210→		doseRate = CalculateDoseRate(channels, liveTime, calibration)
   211→	}
   212→
   213→	countRate := 0.0
   214→	if liveTime > 0 {
   215→		countRate = float64(sumChannels(channels)) / liveTime
   216→	}
   217→
   218→	marker := &database.Marker{
   219→		Lat:         0, // No coordinates in this N42 format
   220→		Lon:         0,
   221→		DoseRate:    doseRate,
   222→		CountRate:   countRate,
   223→		Date:        timestamp,
   224→		HasSpectrum: true,
   225→		Detector:    deviceModel,
   226→	}
   227→
   228→	return spectrum, marker, nil
   229→}
