   231→// parseChannelData parses space-separated channel counts from N42 format.
   232→func parseChannelData(data string) ([]int, error) {
   233→	data = strings.TrimSpace(data)
   234→	if data == "" {
   235→		return nil, fmt.Errorf("empty channel data")
   236→	}
   237→
   238→	fields := strings.Fields(data)
   239→	channels := make([]int, 0, len(fields))
   240→
   241→	for _, field := range fields {
   242→		count, err := strconv.Atoi(field)
   243→		if err != nil {
   244→			return nil, fmt.Errorf("parse channel count %q: %w", field, err)
   245→		}
   246→		channels = append(channels, count)
   247→	}
   248→
   249→	return channels, nil
   250→}
