   252→// parseN42Duration parses ISO 8601 duration (e.g., "PT60S" = 60 seconds).
   253→func parseN42Duration(duration string) (float64, error) {
   254→	duration = strings.TrimSpace(duration)
   255→	if duration == "" {
   256→		return 0, fmt.Errorf("empty duration")
   257→	}
   258→
   259→	// Simple parser for PT{n}S format
   260→	if strings.HasPrefix(duration, "PT") && strings.HasSuffix(duration, "S") {
   261→		seconds := strings.TrimPrefix(duration, "PT")
   262→		seconds = strings.TrimSuffix(seconds, "S")
   263→		val, err := strconv.ParseFloat(seconds, 64)
   264→		if err != nil {
   265→			return 0, err
   266→		}
   267→		return val, nil
   268→	}
   269→
   270→	// Handle PT{n}M format (minutes)
   271→	if strings.HasPrefix(duration, "PT") && strings.HasSuffix(duration, "M") {
   272→		minutes := strings.TrimPrefix(duration, "PT")
   273→		minutes = strings.TrimSuffix(minutes, "M")
   274→		val, err := strconv.ParseFloat(minutes, 64)
   275→		if err != nil {
   276→			return 0, err
   277→		}
   278→		return val * 60, nil
   279→	}
   280→
   281→	return 0, fmt.Errorf("unsupported duration format: %s", duration)
   282→}
