   284→// parseN42CalibrationEquation parses energy calibration coefficients from equation string.
   285→func parseN42CalibrationEquation(coeffStr string) (*database.EnergyCalibration, error) {
   286→	if coeffStr == "" {
   287→		return nil, fmt.Errorf("no calibration coefficients")
   288→	}
   289→
   290→	fields := strings.Fields(coeffStr)
   291→	if len(fields) < 2 {
   292→		return nil, fmt.Errorf("insufficient calibration coefficients")
   293→	}
   294→
   295→	a, err := strconv.ParseFloat(fields[0], 64)
   296→	if err != nil {
   297→		return nil, err
   298→	}
   299→
   300→	b, err := strconv.ParseFloat(fields[1], 64)
   301→	if err != nil {
   302→		return nil, err
   303→	}
   304→
   305→	c := 0.0
   306→	if len(fields) >= 3 {
   307→		c, _ = strconv.ParseFloat(fields[2], 64)
   308→	}
   309→
   310→	return &database.EnergyCalibration{A: a, B: b, C: c}, nil
   311→}
